"""Standalone, offline mobile wireframes. Does not modify or call the live app."""
from pathlib import Path
import json
from html import escape

OUT = Path(__file__).parent
screens = []

def button(label, target, primary=False):
    return f'<button type="button" class="action {"main" if primary else ""}" data-go="{target}">{label}</button>'

def actions(*items):
    return '<div class="actions">' + ''.join(items) + '</div>'

def field(label, value='', kind='text'):
    if kind == 'textarea':
        control = f'<textarea rows="4" placeholder="{escape(value)}"></textarea>'
    elif kind == 'select':
        control = '<select>' + ''.join(f'<option>{escape(x)}</option>' for x in value.split('|')) + '</select>'
    else:
        control = f'<input type="{kind}" placeholder="{escape(value)}">'
    return f'<label class="field">{label}{control}</label>'

def check(label):
    return f'<label class="check"><input type="checkbox"><span>{label}</span></label>'

def text(value):
    return '<p>' + value + '</p>'

def title(value):
    return '<h2>' + value + '</h2>'

def note(value):
    return '<div class="notice">' + value + '</div>'

def placeholder(label, height=140):
    return f'<div class="placeholder" style="min-height:{height}px"><span>{label}</span></div>'

def row(name, detail, target, badge=''):
    return f'<button type="button" class="list-row" data-go="{target}"><span><strong>{name}</strong><small>{detail}</small></span><span class="row-end">{f"<em>{badge}</em>" if badge else ""} ›</span></button>'

def chips(*labels):
    return '<div class="chips">' + ''.join('<span>' + x + '</span>' for x in labels) + '</div>'

def pager(target):
    return '<div class="pagination">' + button('Anterior', target) + '<span>1 de 2</span>' + button('Siguiente', target) + '</div>'

def add(id, role, module, name, body, rule, route='', back=None, nav=True):
    screens.append(dict(id=id, role=role, module=module, name=name, body=body, rule=rule, route=route, back=back, nav=nav))

