by_id = {s['id']:s for s in screens}
import re
for s in screens:
    for target in re.findall(r'data-go="([A-Z][0-9]+)"',s['body']):
        assert target in by_id, (s['id'],target)
    assert not s['back'] or s['back'] in by_id

